package com.fandazi.feature.cart;
import java.util.*; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/cart/drafts") public class CartController { private final CartService carts; public CartController(CartService carts){this.carts=carts;} public record CreateDraftRequest(Long merchantId){} @PostMapping public CartDraft create(@AuthenticationPrincipal Long userId,@RequestBody CreateDraftRequest request){return carts.createDraft(userId,request.merchantId());}@PutMapping("/{id}/items") public CartDraft items(@AuthenticationPrincipal Long userId,@PathVariable Long id,@RequestBody List<CartItemCommand> items){return carts.replaceItems(userId,id,items);}@PostMapping("/{id}/validate") public CartQuote validate(@AuthenticationPrincipal Long userId,@PathVariable Long id){return carts.validate(userId,id);} }
